    @Test
    public void testCollatedIteratorWithMultipleIterators() {
        Comparator<Integer> naturalOrder = Comparator.naturalOrder();
        Iterator<Integer> it1 = Arrays.asList(1, 5, 10).iterator();
        Iterator<Integer> it2 = Arrays.asList(2, 3, 8).iterator();
        Iterator<Integer> it3 = Arrays.asList(4, 6, 7).iterator();

        Iterator<Integer> collated = IteratorUtils.collatedIterator(naturalOrder, it1, it2, it3);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8, 10);
        int index = 0;
        while (collated.hasNext()) {
            assertEquals("Element at index " + index + " is incorrect", expected.get(index), collated.next());
            index++;
        }
        assertEquals("Iterator should have no more elements", 9, index);
    }

    @Test
    public void testCollatedIteratorWithVaryingLengths() {
        Comparator<Integer> naturalOrder = Comparator.naturalOrder();
        Iterator<Integer> it1 = Arrays.asList(1, 10).iterator();
        Iterator<Integer> it2 = Arrays.asList(2, 3, 4, 5).iterator();

        Iterator<Integer> collated = IteratorUtils.collatedIterator(naturalOrder, it1, it2);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 10);
        int index = 0;
        while (collated.hasNext()) {
            assertEquals(expected.get(index), collated.next());
            index++;
        }
        assertEquals(expected.size(), index);
    }

    @Test
    public void testCollatedIteratorWithEmptyIterators() {
        Comparator<Integer> naturalOrder = Comparator.naturalOrder();
        Iterator<Integer> it1 = Collections.emptyIterator();
        Iterator<Integer> it2 = Arrays.asList(1, 2).iterator();
        Iterator<Integer> it3 = Collections.emptyIterator();

        Iterator<Integer> collated = IteratorUtils.collatedIterator(naturalOrder, it1, it2, it3);

        assertTrue(collated.hasNext());
        assertEquals(Integer.valueOf(1), collated.next());
        assertEquals(Integer.valueOf(2), collated.next());
        assertFalse(collated.hasNext());
    }

    @Test
    public void testCollatedIteratorWithSingleIterator() {
        Comparator<Integer> naturalOrder = Comparator.naturalOrder();
        Iterator<Integer> it1 = Arrays.asList(3, 1, 2).iterator();

        Iterator<Integer> collated = IteratorUtils.collatedIterator(naturalOrder, it1);

        // Note: Collating a single iterator with a comparator effectively sorts it 
        // if the CollatingIterator implementation pulls all or manages it via the comparator.
        // In Commons Collections, CollatingIterator works by comparing heads of iterators.
        // For a single iterator, it just returns the elements as they are provided, 
        // but the comparator is still used if it were to compare against others.
        // Actually, CollatingIterator logic depends on comparing heads. 
        // With one iterator, it just behaves like that iterator.

        int count = 0;
        while (collated.hasNext()) {
            collated.next();
            count++;
        }
        assertEquals(3, count);
    }

    @Test
    public void testCollatedIteratorWithReverseComparator() {
        Comparator<Integer> reverseOrder = Comparator.reverseOrder();
        Iterator<Integer> it1 = Arrays.asList(1, 10).iterator();
        Iterator<Integer> it2 = Arrays.asList(2, 9).iterator();

        Iterator<Integer> collated = IteratorUtils.collatedIterator(reverseOrder, it1, it2);

        // Expected order: 10, 9, 2, 1 (highest first)
        // Wait, let's trace: heads are 1 and 2. reverseOrder.compare(1, 2) returns 1. 
        // So 2 is "smaller" in reverse logic? No, reverseOrder.compare(1, 2) is positive.
        // In CollatingIterator, it picks the element that is "less" according to the comparator.
        // For reverseOrder, 10 is "less" than 1.

        // Let's use a simpler set:
        Iterator<Integer> a = Arrays.asList(1, 5).iterator();
        Iterator<Integer> b = Arrays.asList(2, 4).iterator();
        // Reverse order: 5, 4, 2, 1
        Iterator<Integer> collatedRev = IteratorUtils.collatedIterator(reverseOrder, a, b);

        assertEquals(Integer.valueOf(2), collatedRev.next()); // compare(1,2) > 0, so 2 is "smaller"
        assertEquals(Integer.valueOf(1), collatedRev.next());
        assertEquals(Integer.valueOf(4), collatedRev.next());
        assertEquals(Integer.valueOf(5), collatedRev.next());
        // Note: The behavior of CollatingIterator depends on whether it's a min-heap or max-heap approach.
        // It picks the element 'e' such that comparator.compare(e, next_e) <= 0.
    }

    @Test
    public void testCollatedIteratorWithStrings() {
        Comparator<String> naturalOrder = Comparator.naturalOrder();
        Iterator<String> it1 = Arrays.asList("apple", "cherry").iterator();
        Iterator<String> it2 = Arrays.asList("banana", "date").iterator();

        Iterator<String> collated = IteratorUtils.collatedIterator(naturalOrder, it1, it2);

        assertEquals("apple", collated.next());
        assertEquals("banana", collated.next());
        assertEquals("cherry", collated.next());
        assertEquals("date", collated.next());
        assertFalse(collated.hasNext());
    }
